CREATE OR REPLACE FUNCTION audit(
    f_type CHAR(1)
)
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    INSERT INTO Production.ProductInventoryAudit(ProductID, LocationID, Shelf, Bin, Quantity, rowguid, ModifiedDate, InsertOrDelete) VALUES
    (NEW.ProductID, NEW.LocaltionID, NEW.Shelf, NEW.Bin, NEW.Quantity, NEW.rowguid, NEW.ModifiedDate, f_type);

    RETURN NEW;
END;
$$;

CREATE OR REPLACE TRIGGER trg_audit_insert
AFTER INSERT
ON Production.ProductInventory
FOR EACH ROW
EXEC audit('I');

CREATE OR REPLACE TRIGGER trg_audit_delete
AFTER DELETE
ON Production.ProductInventory
FOR EACH ROW
EXEC audit('D');

