CREATE OR REPLACE PROCEDURE update_level()
USING plpgsql
AS $$
BEGIN
    UPDATE Employee
    SET Level = 2
    WHERE Level = 1
        AND EXTRACT(YEAR FROM AGE(CURRENT_DATE - StartDate)) >= 3;
END;
$$;

