CREATE OR REPLACE FUNCTION trg_fn_project_modules_reject_insert()
RETURNS TRIGGER 
AS
$$
BEGIN
    IF NEW.ProjectModulesDate >= (SELECT ProjectStartDate FROM Projects WHERE NEW.ProjectID = ProjectID)
        RAISE EXCEPTION 'ProjectModulesDate is cannot be sooner than ProjectStartDate';
    END IF;

    IF NEW.ProjectModulesCompletedOn <= (SELECT ProjectCompletedOn FROM Projects WHERE NEW.ProjectID = ProjectID)
        RAISE EXCEPTION 'ProjectModulesCompletedOn is cannot be later than ProjectCompletedOn';
    END IF;

    RETURN NEW
IF 

END;
$$;

CREATE OR REPLACE TRIGGER trg_reject_insert
BEFORE INSERT 
ON ProjectModules
EXEC trg_fn_project_modules_reject_insert();

